const items = $input.all();
const results = [];
for (const item of items) {
  const d = item.json;
  const da = Number(d.domain_authority || 0);
  const backlinks = Number(d.backlinks || 0);
  const estValue = (d.appraisal_usd || 100) * 5.60;
  let score = 55;
  let priority = 'NORMAL';
  if (da >= 30 || backlinks >= 1000) { score = 95; priority = 'CRITICAL_BUG'; }
  else if (da >= 15 || backlinks >= 200) { score = 80; priority = 'HIGH'; }
  if (score >= 70) {
    results.push({
      json: {
        category: 'expired_domain',
        title: `Domínio Expirando: ${d.domain || 'exemplo.com.br'}`,
        description: `Autoridade DA: ${da} | Backlinks: ${backlinks} | Tráfego Residual. Valor est. de revenda: R$ ${estValue.toFixed(2)}`,
        opportunity_price: 40.00,
        original_price: estValue,
        net_profit_estimate: Number((estValue - 40).toFixed(2)),
        source_name: 'Registro.br Drop',
        source_url: `https://registro.br/busca-dominio/?q=${d.domain || ''}`,
        evaluation_score: score,
        priority
      }
    });
  }
}
return results;
